@Entity
class Kategori {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String nama;

    @OneToMany(mappedBy = "kategori", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Tugas> daftar = new ArrayList<>();

    protected Kategori() {
    }

    Kategori(String nama) {
        this.nama = nama;
    }

    void tambah(Tugas t) {
        daftar.add(t);
        t.setKategori(this);
    }

    void buang(Tugas t) {
        daftar.remove(t);
        t.setKategori(null);
    }

    Long getId() {
        return id;
    }

    String getNama() {
        return nama;
    }

    List<Tugas> getDaftar() {
        return daftar;
    }
}

@Entity
class Tugas {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String judul;

    @ManyToOne(fetch = FetchType.LAZY)
    private Kategori kategori;

    protected Tugas() {
    }

    Tugas(String judul) {
        this.judul = judul;
    }

    String getJudul() {
