        kategori = k;
    }
}

class Jpa {
    static EntityManagerFactory buat(boolean tampilkanSql, Class<?>... entity) {
        Configuration cfg = new Configuration()
                .setProperty("hibernate.connection.url", "jdbc:h2:mem:toko;DB_CLOSE_DELAY=-1")
                .setProperty("hibernate.connection.username", "sa")
                .setProperty("hibernate.hbm2ddl.auto", "create")
                .setProperty("hibernate.show_sql", String.valueOf(tampilkanSql));
        for (Class<?> k : entity) {
            cfg.addAnnotatedClass(k);
        }
        return cfg.buildSessionFactory();
    }
}

